jQuery(document).ready(function($){var container=$('#wheel-wrapper'),wheelId=container.data('wheel-id'),nonce=container.data('nonce'),rawSettings=container.attr('data-wheel-settings'),rawPrizes=container.attr('data-wheel-prizes'),wheelSettings={},wheelPrizes=[],spinning=false,currentRotation=0;function parseJson(value,fallback){if(!value)return fallback;try{var parsed=JSON.parse(value);return parsed!==null?parsed:fallback}catch(e){return typeof value==='object'?value:fallback}}function normalizeSettings(settings){settings=settings||{};var background=settings.background||{},backgroundColor='#ffffff',backgroundImage='',backgroundType='color';if(typeof background==='string')backgroundColor=background;else if(typeof background==='object'&&background!==null){backgroundType=background.type||'color';backgroundColor=background.value||background.color||'#ffffff';backgroundImage=background.image||'';}return{background:{type:backgroundType,color:backgroundColor,image:backgroundImage},wheel:settings.wheel||{size:500,border:8,border_color:'#ffffff',shadow:true},button:settings.button||{text:'QUAY NGAY',color:'#ff0000',text_color:'#ffffff',radius:50,background_image:''},pointer:settings.pointer||{image:'',size:80},font:settings.font||{family:'Arial',size:20},animation:settings.animation||{duration:6,confetti:true},audio:settings.audio||{spin:'',win:''},custom_css:settings.custom_css||''}}function updateResultCount(){var count=$('#wheel_result').children().length;$('#result_count').text(count)}function getPrizeIndex(prize){return wheelPrizes.findIndex(function(item){return item.id===prize.id||item.title===prize.title})}function drawPointer(ctx,centerX,centerY,radius){ctx.save();ctx.fillStyle='#111';ctx.beginPath();ctx.moveTo(centerX,centerY-radius-12);ctx.lineTo(centerX-16,centerY-radius+18);ctx.lineTo(centerX+16,centerY-radius+18);ctx.closePath();ctx.fill();ctx.restore()}function drawWheelCanvas(rotation){var canvas=document.getElementById('wheel');if(!canvas||!wheelPrizes.length)return;var size=wheelSettings.wheel.size,ctx=canvas.getContext('2d'),centerX=size/2,centerY=size/2,radius=centerX-wheelSettings.wheel.border,segmentCount=wheelPrizes.length,angleStep=2*Math.PI/segmentCount;canvas.width=size;canvas.height=size;canvas.style.width=size+'px';canvas.style.height=size+'px';ctx.clearRect(0,0,size,size);ctx.save();ctx.translate(centerX,centerY);ctx.rotate(rotation);ctx.translate(-centerX,-centerY);if(wheelSettings.wheel.shadow){ctx.shadowColor='rgba(0,0,0,0.15)';ctx.shadowBlur=20;}ctx.beginPath();ctx.arc(centerX,centerY,radius,0,2*Math.PI);ctx.fillStyle=wheelSettings.background.color;ctx.fill();ctx.lineWidth=wheelSettings.wheel.border;ctx.strokeStyle=wheelSettings.wheel.border_color;ctx.stroke();ctx.shadowColor='transparent';wheelPrizes.forEach(function(prize,index){var startAngle=index*angleStep,endAngle=startAngle+angleStep,fillColor=prize.color||(index%2===0?'#f16f6f':'#f6c85f');ctx.beginPath();ctx.moveTo(centerX,centerY);ctx.arc(centerX,centerY,radius,startAngle,endAngle);ctx.closePath();ctx.fillStyle=fillColor;ctx.fill();ctx.strokeStyle='#ffffff';ctx.lineWidth=2;ctx.stroke();ctx.save();var textAngle=startAngle+angleStep/2,textRadius=radius*0.65;ctx.translate(centerX+Math.cos(textAngle)*textRadius,centerY+Math.sin(textAngle)*textRadius);ctx.rotate(textAngle+Math.PI/2);ctx.fillStyle='#ffffff';ctx.font=wheelSettings.font.size+'px '+wheelSettings.font.family;ctx.textAlign='center';ctx.textBaseline='middle';var text=prize.title||prize.name||'Prize',lines=text.split('\n');lines.forEach(function(line,lineIndex){ctx.fillText(line,0,(lineIndex-(lines.length-1)/2)*(wheelSettings.font.size+2))});ctx.restore()});ctx.restore();drawPointer(ctx,centerX,centerY,radius)}function renderWheel(){var wrapper=$('#wheel-wrapper');wrapper.css({backgroundColor:wheelSettings.background.color,backgroundImage:wheelSettings.background.image?'url('+wheelSettings.background.image+')':'none',backgroundSize:wheelSettings.background.image?'cover':'auto',backgroundRepeat:wheelSettings.background.image?'no-repeat':'repeat',backgroundPosition:wheelSettings.background.image?'center center':'center'});$('#spin').text(wheelSettings.button.text||'QUAY NGAY');$('#spin').css({backgroundColor:wheelSettings.button.background_image?'transparent':wheelSettings.button.color,backgroundImage:wheelSettings.button.background_image?'url('+wheelSettings.button.background_image+')':'none',color:wheelSettings.button.text_color,borderRadius:wheelSettings.button.radius+'px',backgroundSize:wheelSettings.button.background_image?'cover':'',backgroundRepeat:wheelSettings.button.background_image?'no-repeat':'',backgroundPosition:wheelSettings.button.background_image?'center center':''});if(wheelSettings.custom_css){var styleId='wp-spin-wheel-custom-css-'+wheelId,styleTag=document.getElementById(styleId);if(!styleTag){styleTag=document.createElement('style');styleTag.id=styleId;document.head.appendChild(styleTag)}styleTag.textContent=wheelSettings.custom_css}drawWheelCanvas(currentRotation)}function animateSpin(targetIndex,callback){if(spinning||!wheelPrizes.length)return;spinning=true;var segmentCount=wheelPrizes.length,angleStep=2*Math.PI/segmentCount,normalizedRotation=currentRotation%(2*Math.PI);if(normalizedRotation<0)normalizedRotation+=2*Math.PI;var targetAngle=2*Math.PI-(targetIndex+0.5)*angleStep,rotations=4,totalRotation=rotations*2*Math.PI+targetAngle-normalizedRotation;if(totalRotation<0)totalRotation+=2*Math.PI;var duration=(wheelSettings.animation.duration||6)*1e3,startRotation=currentRotation,startTime=null;function step(timestamp){if(!startTime)startTime=timestamp;var elapsed=timestamp-startTime,progress=Math.min(elapsed/duration,1),ease=1-Math.pow(1-progress,3),rotation=startRotation+totalRotation*ease;currentRotation=rotation;drawWheelCanvas(currentRotation);if(progress<1){requestAnimationFrame(step);return}spinning=false;currentRotation=(startRotation+totalRotation)%(2*Math.PI);drawWheelCanvas(currentRotation);if(wheelSettings.animation.confetti&&typeof window.confetti==='function')window.confetti();if(typeof callback==='function')callback()}requestAnimationFrame(step)}function handleSpinSuccess(prize){var index=getPrizeIndex(prize);if(index===-1)index=0;animateSpin(index,function(){var title=prize.title||'',description=prize.description||'',resultEntry='<div class="wheel-result-item"><strong>'+title+'</strong><div>'+description+'</div></div>';$('#wheel_result').append(resultEntry);updateResultCount();$('#tab-result').trigger('click')})}wheelSettings=normalizeSettings(parseJson(rawSettings));wheelPrizes=parseJson(rawPrizes)||[];renderWheel();$('#tab-entries').on('click',function(){$('#tab-entries').addClass('active');$('#tab-result').removeClass('active');$('#tab-content-entries').addClass('show active');$('#tab-content-result').removeClass('show active')});$('#tab-result').on('click',function(){$('#tab-result').addClass('active');$('#tab-entries').removeClass('active');$('#tab-content-result').addClass('show active');$('#tab-content-entries').removeClass('show active')});$('#spin').on('click',function(){if(spinning)return;var form={};container.find('.spin-wheel-form input').each(function(){var name=$(this).attr('name');if(name){form[name]=$(this).val()}});$.ajax({url:wp_spin_wheel_params.ajax_url,type:'POST',dataType:'json',data:{action:'spin_wheel_spin',wheel_id:wheelId,nonce:nonce,form:form},success:function(response){if(response.success){handleSpinSuccess(response.data.prize)}else{alert(response.data.message||wp_spin_wheel_params.text_error)}},error:function(){alert(wp_spin_wheel_params.text_error)}})});$('#btn-clear-result').on('click',function(){$('#wheel_result').empty();updateResultCount()})});